static cJSON *agent_messages;
static unsigned long agent_epoch, agent_serial;
static int agent_ready, agent_syncing, agent_child_status;
static char *agent_init_error;

static const char agent_skills[] =
"Inside nextvi, use the ex tool with a JSON object whose command key holds an "
"ex command chain. Inspect before editing. Tools access all buffers "
"regardless of scope; scope is a snapshot, not a live selection.\n"
"Nextvi is not Vim or traditional vi/ex.\n"
"If unsure how an editor command behaves and a mistake could change or lose "
"data, stop and confirm with the user. Completed edits survive errors and "
"cancellation; inspect before retrying.\n"
"Protect context: tool output is uncapped and history is never compacted or "
"silently truncated.\n"
"\n"
"Ex syntax: [range]command[space arguments]. Use one space before arguments "
"to avoid command-name ambiguity. Commands are separated by colon, not "
"vertical bar.\n"
"In arguments, % expands to the current pathname, %# to the previous "
"pathname. !command! expands shell stdout/stderr.\n"
"Escape literal colon, percent and exclamation with backslash.\n"
"Backslashes directly before specials are halved; an odd "
"count quotes the special. Elsewhere backslashes are literal.\n"
"JSON escaping adds another layer: {\"command\":\"p literal\\\\: colon\"}.\n"
"Top-level % addresses need no escape; nested command bodies need escaped %.\n"
"Each nested body adds an ex argument-expansion layer.\n"
"\n"
"Ranges: lines are one-based, character offsets zero-based with exclusive "
"ends. . is current position, $ last line or end of line, % whole buffer. "
"Comma separates line endpoints; semicolon introduces character positions. +N "
"and -N offset a position; # rebases to the previous range value. >regex> "
"searches forward, <regex< backward. A range without a command moves the "
"cursor.\n"
"Keep ranges within buffer bounds. Empty buffers have no printable lines.\n"
"\n"
"Edit commands (change buffer text):\n"
"[vrange]i text: insert AFTER the addressed line; 0i inserts before line 1.\n"
"Example: 0i hello.\n"
"[range]c text: replace the addressed text.\n"
"Examples: 1,3c hello; 1;1,1;4c XYZ.\n"
"For tool i/c calls, supply text directly with literal newlines, no dot "
"terminator or keyboard escape. Text is required.\n"
"[range]s/regex/replacement/[flags]: replace the first match per line; g "
"replaces all matches, m enables multiline matching. Returns error if nothing "
"is replaced. Parentheses capture groups; replacement backreferences use \\0 "
"for the whole match, \\1 etc. for groups (double backslashes in JSON).\n"
"Example: 1,50s/old/new/g.\n"
"range! command: pipe the addressed text to a shell command and REPLACE that "
"text with stdout/stderr. Any range, including . or %, makes ! a buffer edit. "
"Use only when replacement is intended, never to inspect output.\n"
"Example: 1,10!sort replaces lines 1 through 10 with sorted output.\n"
"\n"
"Print commands (inspect output):\n"
"DO NOT USE %p or dump whole buffers. First check :$= for "
"line count (second number). Print only needed ranges in separate small "
"chunks, e.g. 1,50p then 51,100p, within the line count. Stop when you have "
"enough context. Use character ranges for long lines. Bound g prints and "
"shell output too.\n"
"[range]p [text]: print addressed text, or the evaluated argument if "
"supplied. Prefer explicit ranges.\n"
"Examples: 10,20p prints lines 10 through 20; 1;1,1;4p prints offsets 1 "
"through 3 of line 1; p % prints the pathname.\n"
"$= prints range numbers; the second is the buffer line count.\n"
"! command WITHOUT A RANGE: run a shell command and return stdout/stderr "
"without replacing buffer text. Nonzero exit status is an error. The shell "
"command itself can still modify files.\n"
"Example: !pwd prints the working directory. Do not add % or a line range.\n"
"\n"
"Search commands:\n"
"[range]f> regex: search forward within the range and move to the match; no "
"range searches only the current line. No argument reuses the previous regex. "
"Returns error if not found.\n"
"Example: 1,100f> int. >int>p prints the next line matching int.\n"
"[range]g/regex/command: execute command on matching lines; g! selects "
"nonmatching lines. Default range is the whole buffer, or current line when "
"nested. Returns error if no line matches or command fails. Escape colons "
"within the body to chain commands there. The body determines whether g "
"prints or edits.\n"
"Print example: 1,50g/TODO/p.\n"
"Edit example: 1,50g/TODO/s/old/new/g.\n";

static cJSON *agent_msg(const char *role, const char *content)
{
	cJSON *m = cJSON_CreateObject();
	cJSON_AddStringToObject(m, "role", role);
	cJSON_AddStringToObject(m, "content", content);
	return m;
}

static char *agent_text(struct lbuf *lb)
{
	sbuf_smake(sb, 256)
	for (int i = 0; i < lbuf_len(lb); i++)
		sbuf_str(sb, lb->ln[i])
	sbufn_ret(sb, sb->s)
}

/* Remove terminal control sequences before either capture or display. */
static void agent_plain(sbuf *out, const char *s)
{
	while (*s) {
		unsigned char c = *s++;
		if (c == 27) {
			if (*s == '\''['\'') {
				s++;
				while (*s && !(*s >= '\''@'\'' && *s <= '\''~'\'')) s++;
				if (*s) s++;
			} else if (*s == '\'']'\'' || *s == '\''P'\'' || *s == '\''^'\'' || *s == '\''_'\'') {
				s++;
				while (*s && *s != 7 && !(*s == 27 && s[1] == '\''\\'\'')) s++;
				if (*s == 7) s++;
				else if (*s) s += 2;
			} else if (*s) s++;
		} else if (c == '\''\n'\'' || c == '\''\t'\'' || (c >= 32 && c != 127))
			sbuf_chr(out, c)
	}
	sbuf_nul(out)
}

static int agent_writeall(int fd, const char *s, size_t n)
{
	while (n) {
		ssize_t k = write(fd, s, n);
		if (k < 0 && errno == EINTR) continue;
		if (k <= 0) return -1;
		s += k;
		n -= k;
	}
	return 0;
}

static void agent_output(const char *s)
{
	sbuf_smake(sb, 256)
	agent_plain(sb, s);
	agent_writeall(STDOUT_FILENO, sb->s, sb->s_n);
	free(sb->s);
}

static int agent_save(int i)
{
	struct buf *b = tempbufs + i;
	char *path = emalloc(strlen(b->path) + 16);
	int fd, ret = -1;
	sprintf(path, "%s.XXXXXX", b->path);
	fd = mkstemp(path);
	if (fd >= 0) {
		ret = lbuf_wr(b->lb, fd, 0, lbuf_len(b->lb));
		if (fsync(fd)) ret = -1;
		if (close(fd)) ret = -1;
		if (!ret && rename(path, b->path)) ret = -1;
		if (!ret) b->mtime = mtime(b->path);
		unlink(path);
	}
	free(path);
	return ret;
}

static void agent_sync(struct lbuf *lb)
{
	if (!agent_ready || agent_syncing) return;
	for (int i = 3; i < 5; i++) {
		if (tempbufs[i].lb != lb) continue;
		agent_syncing = 1;
		if (agent_save(i))
			ex_print("agent write failed; buffer text retained", msg_ft)
		agent_syncing = 0;
	}
}

static int agent_mkdir(char *path)
{
	struct stat st;
	for (char *p = path + 1; ; p++) {
		char c = *p;
		if (c && c != '\''/'\'') continue;
		*p = 0;
		int failed = (mkdir(path, 0700) && errno != EEXIST) ||
			stat(path, &st) || !S_ISDIR(st.st_mode);
		*p = c;
		if (failed) return -1;
		if (!c) return 0;
	}
}

static void agent_history(int edited)
{
	char *s = agent_text(tempbufs[4].lb);
	cJSON_Delete(agent_messages);
	agent_messages = cJSON_CreateArray();
	cJSON_AddItemToArray(agent_messages, agent_msg("system", s));
	free(s);
	if (edited) {
		s = agent_text(tempbufs[3].lb);
		cJSON_AddItemToArray(agent_messages, agent_msg("user", s));
		free(s);
	}
}

static void agent_init(void)
{
	const char *home = getenv("HOME");
	char *dir, *path;
	temp_open(3, "/conversation/", _ft);
	temp_open(4, "/skills/", _ft);
	lbuf_edit(tempbufs[4].lb, (char *)agent_skills, 0, 0, 0, 0);
	lbuf_saved(tempbufs[4].lb, 1);
	if ((!log_dir && (!home || !*home)) || (log_dir && !*log_dir)) {
		agent_init_error = "agent log directory is not configured";
		return;
	}
	dir = emalloc(strlen(log_dir ? log_dir : home) + 64);
	if (log_dir) strcpy(dir, log_dir);
	else sprintf(dir, "%s/.nextvi/logs", home);
	if (agent_mkdir(dir)) goto fail;
	strcat(dir, "/session-XXXXXX");
	if (!mkdtemp(dir)) goto fail;
	/* Absolute paths survive :cd during the session. */
	if (*dir != '\''/'\'') {
		char *cwd = getcwd(NULL, 0);
		if (!cwd) goto fail;
		path = emalloc(strlen(cwd) + strlen(dir) + 2);
		sprintf(path, "%s/%s", cwd, dir);
		free(cwd);
		free(dir);
		dir = path;
	}
	for (int i = 3; i < 5; i++) {
		path = emalloc(strlen(dir) + 32);
		sprintf(path, "%s/%s", dir, i == 3 ? "conversation" : "skills");
		free(tempbufs[i].path);
		tempbufs[i].path = path;
		tempbufs[i].plen = strlen(path);
		if (agent_save(i)) goto fail;
	}
	agent_ready = 1;
	agent_history(0);
	free(dir);
	return;
	fail:
	free(dir);
	agent_init_error = "cannot create agent session files";
}

static void agent_log(const char *role, const char *text)
{
	sbuf_smake(sb, 256)
	sbuf_str(sb, role)
	sbuf_chr(sb, '\''\n'\'')
	agent_plain(sb, text);
	if (sb->s[sb->s_n-1] != '\''\n'\'') sbuf_chr(sb, '\''\n'\'')
	sbuf_chr(sb, '\''\n'\'')
	sbuf_nul(sb)
	agent_output(sb->s);
	tempbufs[3].lb->useq++;
	lbuf_edit(tempbufs[3].lb, sb->s, lbuf_len(tempbufs[3].lb),
		lbuf_len(tempbufs[3].lb), 0, 0);
	tempbufs[3].lb->useq++;
	free(sb->s);
}

static void agent_key(int c)
{
	if (c == TK_CTL('\''c'\'')) agent_cancel = 1;
	if (c == TK_CTL('\''o'\'')) agent_pause = 1;
	if (c == TK_CTL('\''l'\'')) term_winch = 1;
}

static int agent_boundary(void)
{
	while (tibuf_pos < tibuf_cnt) agent_key(term_read(0));
	while (poll(&term_ufd, 1, 0) > 0 && term_ufd.revents & POLLIN)
		agent_key(term_read(0));
	return agent_cancel || agent_pause;
}

/* File-backed stdin avoids pipe deadlocks; poll output and the terminal together. */
static sbuf *agent_process(char **argv, sbuf *input, int *status, int http)
{
	FILE *in = tmpfile();
	struct pollfd fds[2];
	int output[2], pid, done = 0, st = 0, killed = 0;
	char buf[4097];
	sbuf *sb;
	if (!in) return NULL;
	if (input && agent_writeall(fileno(in), input->s, input->s_n)) {
		fclose(in);
		return NULL;
	}
	rewind(in);
	if (pipe(output)) { fclose(in); return NULL; }
	pid = fork();
	if (!pid) {
		setsid();
		dup2(fileno(in), STDIN_FILENO);
		dup2(output[1], STDOUT_FILENO);
		dup2(output[1], STDERR_FILENO);
		close(output[0]); close(output[1]); fclose(in);
		execvp(argv[0], argv);
		_exit(127);
	}
	fclose(in);
	close(output[1]);
	if (pid < 0) { close(output[0]); return NULL; }
	fds[0].fd = output[0]; fds[0].events = POLLIN;
	fds[1] = term_ufd;
	sbuf_make(sb, 4096)
	while (!done || fds[0].fd >= 0) {
		if ((agent_cancel || (http && agent_pause)) && !killed) {
			kill(-pid, SIGKILL);
			killed = 1;
		}
		int n = poll(fds, 2, 100);
		if (n < 0 && errno != EINTR) { agent_cancel = 1; continue; }
		if (fds[0].fd >= 0 && fds[0].revents & (POLLIN | POLLHUP | POLLERR)) {
			int nr = read(fds[0].fd, buf, sizeof(buf)-1);
			if (nr > 0) sbuf_mem(sb, buf, nr)
			else if (!nr || errno != EINTR) {
				close(fds[0].fd);
				fds[0].fd = -1;
			}
		}
		if (fds[1].revents & POLLIN) agent_key(term_read(0));
		if (fds[1].revents & (POLLHUP | POLLERR | POLLNVAL)) {
			agent_cancel = 1;
			fds[1].fd = -1;
		}
		if (!done) done = waitpid(pid, &st, WNOHANG) == pid;
	}
	*status = WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
	sbufn_ret(sb, sb)
}

static sbuf *agent_shell(char *cmd, sbuf *input, int *status)
{
	char *sh = getenv("SHELL"), *argv[] = {sh && *sh ? sh : "sh", "-c", cmd, NULL};
	int st;
	sbuf *out = agent_process(argv, input, &st, 0);
	if (!out) { agent_child_status = 1; return NULL; }
	if (status) *status = st;
	if (st) agent_child_status = st;
	if (agent_capture) agent_plain(agent_capture, out->s);
	return out;
}

static cJSON *agent_config(void)
{
	cJSON *req = cJSON_ParseWithOpts(request_extra, NULL, 1);
	if (!cJSON_IsObject(req) || !api_key || !*api_key ||
		strpbrk(api_key, "\r\n") || !endpoint ||
		(strncmp(endpoint, "http://", 7) && strncmp(endpoint, "https://", 8)) ||
		request_timeout <= 0 || max_tool_rounds <= 0) {
		cJSON_Delete(req);
		return NULL;
	}
	/* Remove every duplicate too, so no provider can interpret a shadow value. */
	const char *owned[] = {"messages", "tools", "stream"};
	for (int i = 0; i < LEN(owned); i++)
		while (cJSON_GetObjectItem(req, owned[i])) cJSON_DeleteItemFromObject(req, owned[i]);
	return req;
}

static char *agent_http(cJSON *req, int *st)
{
	char hdrpath[] = "/tmp/nextvi-header-XXXXXX", timeout[32], hdrarg[80];
	int fd = mkstemp(hdrpath);
	sbuf *out = NULL;
	sbuf_smake(hdr, 128)
	sbuf_str(hdr, "Authorization: Bearer ")
	sbuf_str(hdr, api_key)
	sbuf_chr(hdr, '\''\n'\'')
	if (fd < 0) goto ret;
	if (agent_writeall(fd, hdr->s, hdr->s_n)) { close(fd); goto ret; }
	close(fd);
	snprintf(timeout, sizeof(timeout), "%d", request_timeout);
	sprintf(hdrarg, "@%s", hdrpath);
	char *argv[] = {"curl", "--disable", "--silent", "--show-error", "--fail-with-body",
		"--max-time", timeout, "--header", hdrarg, "--header", "Content-Type: application/json",
		"--data-binary", "@-", "--url", endpoint, NULL};
	sbuf body;
	body.s = cJSON_PrintUnformatted(req);
	body.s_n = strlen(body.s);
	out = agent_process(argv, &body, st, 1);
	free(body.s);
	ret:
	unlink(hdrpath);
	free(hdr->s);
	if (!out) { *st = -1; return NULL; }
	char *s = out->s;
	free(out);
	return s;
}

static char *agent_snapshot(char *loc)
{
	int beg = 0, end = lbuf_len(xb), o1 = -1, o2 = -1;
	char info[160];
	sbuf text;
	if (loc && ex_region(loc, &beg, &end, &o1, &o2)) {
		if (lbuf_len(xb) || strcmp(loc, "%")) return NULL;
		beg = end = 0;
	}
	int last = MAX(0, end-1);
	if (o1 >= 0) o1 = MIN(o1, lbuf_get(xb, beg) ? uc_slen(lbuf_get(xb, beg)) : 0);
	if (o2 >= 0) o2 = MIN(o2, lbuf_get(xb, last) ? uc_slen(lbuf_get(xb, last)) : 0);
	int endoff = o2 >= 0 ? o2 : (lbuf_get(xb, last) ? uc_slen(lbuf_get(xb, last)) : 0);
	sbuf_smake(sb, 256)
	snprintf(info, sizeof(info), "Editor snapshot\nbuffer %d\nname ",
		istempbuf(ex_buf) ? (int)(tempbufs-ex_buf-1) : (int)(ex_buf-bufs));
	sbuf_str(sb, info)
	sbuf_str(sb, xb_path)
	snprintf(info, sizeof(info), "\nrange %d;%d,%d;%d (end character exclusive)\n",
		end ? beg+1 : 0, MAX(o1, 0), end, endoff);
	sbuf_str(sb, info)
	lbuf_region(xb, &text, beg, MAX(o1, 0), last, o2);
	sbuf_str(sb, text.s)
	free(text.s);
	sbufn_ret(sb, sb->s)
}

static void agent_resize(void)
{
	struct winsize win;
	if (!ioctl(term_ufd.fd, TIOCGWINSZ, &win)) {
		if (win.ws_col) xcols = win.ws_col;
		if (win.ws_row) xrows = win.ws_row;
	}
	term_winch = 0;
	term_resized++;
}

/* Reconstruct only a screenful, never replay the entire log to scrollback. */
static void agent_redraw(const char *draft)
{
	char *log = agent_text(tempbufs[3].lb);
	sbuf_smake(sb, 256)
	agent_plain(sb, log);
	if (draft) agent_plain(sb, draft);
	int cap = MAX(2, xrows), *starts = emalloc(sizeof(int) * cap);
	int rows = 1, col = 0;
	starts[0] = 0;
	for (int i = 0; i < sb->s_n; ) {
		char *s = sb->s+i;
		int n = uc_len(s), newline = *s == '\''\n'\'', code;
		uc_code(code, s, n)
		col += *s == '\''\t'\'' ? 8 - col % 8 : MAX(0, uc_wid(code));
		i += MAX(1, n);
		if (newline || col >= MAX(1, xcols)) {
			starts[rows++ % cap] = i;
			col = 0;
		}
	}
	int start = starts[MAX(0, rows - MAX(1, xrows-2)) % cap];
	preserve(int, xled, xled = 1;)
	term_clean();
	restore(xled)
	agent_output(sb->s + start);
	free(starts); free(log); free(sb->s);
}

/* Always recurse from the ex-style conversation into vi, preserving caller state. */
static void agent_editor(void)
{
	preserve(int, xvis, xvis = (xvis | 2) & ~1;)
	preserve(int, agent_tool, agent_tool = 0;)
	preserve(sbuf *, agent_capture, agent_capture = NULL;)
	preserve(int, agent_cancel, agent_cancel = 0;)
	preserve(int, agent_pause, agent_pause = 0;)
	led_modeswap();
	restore(agent_pause)
	restore(agent_cancel)
	restore(agent_capture)
	restore(agent_tool)
	restore(xvis)
}

static void agent_refresh(void)
{
	char *s = agent_snapshot(NULL);
	cJSON_AddItemToArray(agent_messages, agent_msg("user", s));
	agent_log("USER", s);
	free(s);
}

static void agent_sequence(void)
{
	for (int i = 0; i < xbufcur; i++) bufs[i].lb->useq += xseq;
	for (int i = 0; i < LEN(tempbufs); i++) tempbufs[i].lb->useq += xseq;
}

static void agent_run(const char *input)
{
	unsigned long serial = ++agent_serial, epoch = agent_epoch;
	cJSON *req, *root, *message, *calls, *tc, *text;
	char *body;
	int st;
	agent_cancel = agent_pause = 0;
	cJSON_AddItemToArray(agent_messages, agent_msg("user", input));
	agent_log("USER", input);
	for (int round = 0; ; ) {
		req = agent_config();
		if (!req) { agent_log("RESULT", "invalid agent configuration"); return; }
		cJSON_AddItemReferenceToObject(req, "messages", agent_messages);
		cJSON_AddItemToObject(req, "tools", cJSON_Parse("[{\"type\":\"function\",\"function\":{\"name\":\"ex\",\"description\":\"Execute an ex command chain in nextvi\",\"parameters\":{\"type\":\"object\",\"properties\":{\"command\":{\"type\":\"string\"}},\"required\":[\"command\"],\"additionalProperties\":false}}}]"));
		cJSON_AddBoolToObject(req, "stream", 0);
		body = agent_http(req, &st);
		cJSON_Delete(req);
		if (agent_cancel) { free(body); agent_log("RESULT", "cancelled"); return; }
		if (agent_pause) {
			free(body);
			agent_editor();
			agent_redraw(NULL);
			agent_pause = 0;
			if (serial != agent_serial || epoch != agent_epoch || xquit) return;
			agent_log("RESULT", "response skipped after recursive editing");
			agent_refresh();
			continue;
		}
		if (st || !body) {
